import { createHash } from "node:crypto";

export type PersonaScope = {
  tenantId: string;
  organizationId: string;
  projectId: string;
};
export type PersonaAuthority = PersonaScope & {
  principalId: string;
  principalType: "HUMAN" | "AI" | "SERVICE";
  capabilities: readonly string[];
};

/** Pure policy only. Inputs MUST be resolved by existing server authorization,
 * never deserialized from an HTTP body or generated by a model. */
export function assertPersonaScope(
  authority: PersonaAuthority | null,
  resource: PersonaScope | null,
  capability: string,
): void {
  if (
    !authority ||
    !resource ||
    ![
      authority.tenantId,
      authority.organizationId,
      authority.projectId,
      authority.principalId,
      resource.tenantId,
      resource.organizationId,
      resource.projectId,
    ].every((v) => typeof v === "string" && v.trim().length > 0)
  ) {
    throw new Error("PERSONA_SCOPE_REQUIRED");
  }
  if (
    authority.tenantId !== resource.tenantId ||
    authority.organizationId !== resource.organizationId ||
    authority.projectId !== resource.projectId
  ) {
    throw new Error("PERSONA_SCOPE_DENIED");
  }
  if (!authority.capabilities.includes(capability))
    throw new Error("PERSONA_CAPABILITY_DENIED");
  if (
    ["persona.configure_authority", "persona.approve"].includes(capability) &&
    authority.principalType !== "HUMAN"
  ) {
    throw new Error("PERSONA_HUMAN_REQUIRED");
  }
}

/** No legacy role, actionContext or request-supplied project is an authority.
 * Remove this quarantine ONLY when persisted persona ownership, server-issued
 * active-context authorization and atomic budget admission are wired together. */
export function legacyPersonaExecutionBlock(provider: string): string {
  if (provider !== "anthropic") return "PERSONA_PROVIDER_UNSUPPORTED";
  return "PERSONA_SCOPE_AND_BUDGET_BINDING_REQUIRED";
}

export type PersonaApprovalIntent = PersonaScope & {
  accountId: string;
  action: string;
  target: string;
  content: string;
  version: number;
  amountMicros: number | null;
  currency: string | null;
  makerPrincipalId: string;
};

export function personaIntentDigest(intent: PersonaApprovalIntent): string {
  const strings = [
    intent.tenantId,
    intent.organizationId,
    intent.projectId,
    intent.accountId,
    intent.action,
    intent.target,
    intent.makerPrincipalId,
  ];
  if (
    !strings.every(
      (v) => typeof v === "string" && v.trim().length > 0 && v.length <= 512,
    ) ||
    typeof intent.content !== "string" ||
    Buffer.byteLength(intent.content) > 262144 ||
    !Number.isSafeInteger(intent.version) ||
    intent.version < 1 ||
    (intent.amountMicros !== null &&
      (!Number.isSafeInteger(intent.amountMicros) ||
        intent.amountMicros < 0)) ||
    (intent.amountMicros === null
      ? intent.currency !== null
      : !/^[A-Z]{3}$/.test(intent.currency ?? ""))
  ) {
    throw new Error("PERSONA_APPROVAL_INTENT_INVALID");
  }
  // Explicit field order excludes extra caller-controlled properties.
  return createHash("sha256")
    .update(
      JSON.stringify([
        "persona-approval-v1",
        ...strings,
        intent.content,
        intent.version,
        intent.amountMicros,
        intent.currency,
      ]),
    )
    .digest("hex");
}

/** A digest is a binding, NOT proof of approval. Receipt must come from DB. */
export function assertPersonaApproval(
  authority: PersonaAuthority,
  intent: PersonaApprovalIntent,
  receipt: {
    digest: string;
    reviewerPrincipalId: string;
    expiresAt: number;
    status: string;
  },
  now = Date.now(),
): void {
  assertPersonaScope(authority, intent, "persona.approve");
  if (
    authority.principalId === intent.makerPrincipalId ||
    receipt.reviewerPrincipalId !== authority.principalId
  )
    throw new Error("PERSONA_SELF_APPROVAL_DENIED");
  if (
    receipt.status !== "approved" ||
    !Number.isFinite(receipt.expiresAt) ||
    receipt.expiresAt <= now ||
    receipt.digest !== personaIntentDigest(intent)
  )
    throw new Error("PERSONA_APPROVAL_STALE");
}
